"""
The text format the sheets are stored in (data/**/*.txt): one block per
sheet row and one line per non-empty cell, so `git diff` shows exactly
which cells of which rows changed. Each column is written under a short
name (.A, .B, ...) that is listed once at the top, so long column names
aren't repeated on every line of a big tab.

    # GENERATED by scripts/sync_sheets.py from Google Sheets. Do not edit: ...
    # Sheet: https://docs.google.com/spreadsheets/d/.../edit?gid=0#gid=0
    # Tab: dhatu
    HEADER:type=record
    HEADER:key=src_link|dhatu
    HEADER:.A=src_link           one line per column, in the sheet's column order:
    HEADER:.B=dhatu              'HEADER:.<short name>=<column name>'
    HEADER:.C=artha
    ...

    .--- 01.0001 भू              record marker: '.--- ' + the key cell(s) (for reading only)
    .A: 01.0001                  '.<short name>: <value>', in short-name order
    .B: भू
    .C: सत्तायाम्
    a second line of the same cell (lines after the first are written as they are)

  - Short names are stable. A sync keeps the short name each column had in
    the existing file (matched by column name), and a new column gets the
    next letter after the highest one used so far. So adding, removing or
    moving a column in the sheet changes the HEADER lines and that column's
    cells, not every line of every record. After such changes the short
    names need not match the sheet's column letters: the HEADER lines are
    the mapping. A renamed column counts as removed + added (new short name).
  - Every column is listed, so the column layout (including columns that
    are empty in every row, unnamed or with a repeated name) survives the
    round trip.
  - Empty cells are left out; fully empty rows are dropped.
  - A line starting with '.' is always a marker or a field, so a line in a
    cell (after its first line) can't start with '.'. The sync refuses such
    a sheet, naming the row and column.
  - Column names can't contain '|' or a line break.
  - The older format (HEADER:columns=name|name|... and fields written as
    '.<column name>: value') is still read; the next sync, or
    `sync_sheets.py --normalize-only`, rewrites such a file with short names.

This is the same idea as the 'record' format in vagvibha/dict-builder,
except that row 1 of a kosha tab is the column header row (no metadata row).
"""

import re

MARKER = ".---"
MAX_REPORTED = 20
HEADER_RE = re.compile(r"^HEADER:([a-z]+|\.[A-Z]+)=(.*)$")


class FormatError(Exception):
    pass


def column_letter(i):
    """0 -> A, 25 -> Z, 26 -> AA."""
    s, i = "", i + 1
    while i:
        i, r = divmod(i - 1, 26)
        s = chr(65 + r) + s
    return s


def column_index(letters):
    n = 0
    for ch in letters:
        n = n * 26 + ord(ch) - 64
    return n - 1


def _occurrences(header):
    """['a', '', 'a'] -> [('a', 1), ('', 1), ('a', 2)]: tells repeated or
    unnamed columns apart, in order."""
    seen, out = {}, []
    for h in header:
        seen[h] = seen.get(h, 0) + 1
        out.append((h, seen[h]))
    return out


def short_names(header, previous=None):
    """Header -> the short name ('A', 'B', ...) of each column.
    `previous`: [(short name, column name)] of the existing file, in its
    column order (see columns_in), whose short names are kept."""
    prev, nxt = {}, 0
    for (a, _), occ in zip(previous or [], _occurrences([n for _, n in previous or []])):
        prev[occ] = a
        nxt = max(nxt, column_index(a) + 1)
    out = []
    for occ in _occurrences(header):
        a = prev.get(occ)
        if a is None:
            a, nxt = column_letter(nxt), nxt + 1
        out.append(a)
    return out


def _legacy_field_names(header):
    """Old format: the name each column was written under ('[G]' for an
    unnamed or repeated column)."""
    counts = {}
    for h in header:
        counts[h] = counts.get(h, 0) + 1
    return [h if h and counts[h] == 1 else f"[{column_letter(j)}]" for j, h in enumerate(header)]


# ---------------------------------------------------------------- rows -> text
def rows_to_text(rows, comments=(), key=None, previous=None):
    """Tidied, rectangular rows (row 0 = header) -> the file's text.
    `key`: the column, or list of columns, shown on each '.---' marker
    (default: the first column).
    `previous`: the existing file's columns (columns_in), to keep its short names.
    Every problem is reported (up to MAX_REPORTED), by sheet row and column."""
    if not rows or not any(rows[0]):
        raise FormatError("the tab is empty (no header row)")
    header, data = rows[0], rows[1:]
    problems = []
    for j, h in enumerate(header):
        if re.search(r"[|\n]", h):
            problems.append(f"row 1, column {column_letter(j)}: column name {h!r} can't contain "
                            "'|' or a line break")
    keys = [key] if isinstance(key, str) else list(key or [header[0]])
    kjs = []
    for k in keys:
        if not k or header.count(k) != 1:
            raise FormatError(f"key column {k!r} is not a (unique) column; columns are {header}")
        kjs.append(header.index(k))
    short = short_names(header, previous)
    order = sorted(range(len(header)), key=lambda j: column_index(short[j]))

    out = [f"# {c}" for c in comments]
    out += ["HEADER:type=record", "HEADER:key=" + "|".join(keys)]
    out += [f"HEADER:.{short[j]}={h}" for j, h in enumerate(header)]
    for i, row in enumerate(data, start=2):
        if not any(row):
            continue
        label = " ".join(" ".join(row[j].split()) for j in kjs if row[j])
        out += ["", f"{MARKER} {label}".rstrip()]
        for j in order:
            cell = row[j]
            if not cell:
                continue
            first, *rest = cell.split("\n")
            for k, line in enumerate(rest, start=2):
                if line.startswith("."):
                    problems.append(f"row {i}, column {column_letter(j)} ({header[j] or 'unnamed'}): "
                                    f"line {k} of the cell starts with '.' (not allowed after a "
                                    "cell's first line)")
            out.append(f".{short[j]}: {first}")
            out.extend(rest)
    if problems:
        more = len(problems) - MAX_REPORTED
        shown = problems[:MAX_REPORTED] + ([f"... and {more} more"] if more > 0 else [])
        raise FormatError("\n    ".join(["problems in the sheet:"] + shown))
    return "\n".join(out) + "\n"


# ---------------------------------------------------------------- text -> rows
def _parse_header(lines, filename):
    """-> (headers {name: value}, columns [(field name, column name)] in
    sheet order, legacy?, index of the first line after the header)."""
    def err(msg, n):
        return FormatError(f"{filename}:{n}: {msg}")

    headers, columns, n = {}, [], 0
    while n < len(lines):
        line = lines[n]
        if line.startswith("#") or not line.strip():
            n += 1
            continue
        m = HEADER_RE.match(line)
        if not m:
            break
        name, value = m.groups()
        if name.startswith("."):
            if any(a == name[1:] for a, _ in columns):
                raise err(f"short name {name} given twice", n + 1)
            columns.append((name[1:], value))
        elif name in headers:
            raise err(f"HEADER:{name} given twice", n + 1)
        else:
            headers[name] = value
        n += 1
    if headers.get("type") != "record":
        raise err("not a record file (no HEADER:type=record)", 1)
    legacy = "columns" in headers
    if legacy and columns:
        raise err("both HEADER:columns= and HEADER:.<short name>= lines", 1)
    if legacy:
        header = headers["columns"].split("|")
        columns = list(zip(_legacy_field_names(header), header))
    if not columns:
        raise err("no columns (no HEADER:.A=<column name> lines)", 1)
    return headers, columns, legacy, n


def columns_in(text, filename="<text>"):
    """-> [(short name, column name)] of a file, in sheet order, or None for
    a file in the older format (it has no short names to keep)."""
    lines = text.replace("\r\n", "\n").split("\n")
    _, columns, legacy, _ = _parse_header(lines, filename)
    return None if legacy else columns


def parse(text, filename="<text>"):
    """The file's text -> (headers {name: value}, rows) with rows[0] the
    column header and every row as wide as it."""
    def err(msg, n):
        return FormatError(f"{filename}:{n}: {msg}")

    lines = text.replace("\r\n", "\n").split("\n")
    headers, columns, _, n = _parse_header(lines, filename)
    header = [name for _, name in columns]
    pos = {a: j for j, (a, _) in enumerate(columns)}
    width = len(header)

    rows, rec, field = [header], None, None
    for n in range(n, len(lines)):
        line = lines[n]
        if line == MARKER or line.startswith(MARKER + " "):
            rec, field = [None] * width, None
            rows.append(rec)
        elif line.startswith("."):
            name, sep, value = line[1:].partition(": ")
            if not sep:
                raise err(f"bad line {line[:60]!r}: a line starting with '.' must be a "
                          f"'{MARKER} ...' record marker or a '.<short name>: value' field", n + 1)
            if rec is None:
                raise err(f"field before the first '{MARKER}' record marker", n + 1)
            if name not in pos:
                raise err(f"unknown short name {name!r} (no HEADER:.{name}= line)", n + 1)
            field = pos[name]
            if rec[field] is not None:
                raise err(f"column {name!r} given twice in one record", n + 1)
            rec[field] = [value]
        elif field is not None:
            rec[field].append(line)
        elif line.strip():
            raise err(f"text outside a field (expected '{MARKER} ...' or '.<short name>: value')", n + 1)
    for r in rows[1:]:
        for j, v in enumerate(r):
            r[j] = "\n".join(v).rstrip() if v is not None else ""
    return headers, rows


def read(path):
    """-> rows (row 0 = header) of a record file."""
    return parse(path.read_text(encoding="utf-8-sig"), str(path))[1]
